def bfs_start(grid, start_r, start_c):
    visited[start_r][start_c] = True
    comp = [(start_r, start_c)]
    queue = [(start_r, start_c)]
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and not visited[nr][nc]:
                visited[nr][nc] = True
                comp.append((nr, nc))
                queue.append((nr, nc))
    return comp

for r in range(h):
