demo_in = G['Demo pair 2 input']
h, w = len(demo_in), len(demo_in[0])

def find_2x2_blocks(grid):
    blocks = []
    for r in range(len(grid)-1):
        for c in range(len(grid[0])-1):
            if grid[r][c] == 2 and grid[r+1][c] == 2 and grid[r][c+1] == 2 and grid[r+1][c+1] == 2:
                blocks.append((r,c))
    return blocks

def directional_sum(grid, r, c):
    """Sum of 2s extending from the block in 4 directions"""
    total = 0
    # Up (from row r up to top)
    for i in range(r-1, -1, -1):
        total += sum(1 for j in range(c, min(c+2, len(grid[0]))) if grid[i][j] == 2)

    # Down (from row r+1 down to bottom)
    for i in range(r+2, len(grid)):
        total += sum(1 for j in range(c, min(c+2, len(grid[0]))) if grid[i][j] == 2)

    # Left (from col c to left edge)
    for j in range(c-1, -1, -1):
        total += sum(1 for i in range(r, r+2) if grid[i][j] == 2)

    # Right (from col c+1 to right edge)
    for j in range(c+2, len(grid[0])):
        total += sum(1 for i in range(r, r+2) if grid[i][j] == 2)

    return total

