def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

for demo_name in ['Demo pair 1 input', 'Demo pair 2 input']:
    demo_in = G[demo_name]
    h, w = len(demo_in), len(demo_in[0])

    def find_2x2_blocks(grid):
        blocks = []
        for r in range(len(grid)-1):
            for c in range(len(grid[0])-1):
                if grid[r][c] == 2 and grid[r+1][c] == 2 and grid[r][c+1] == 2 and grid[r+1][c+1] == 2:
                    blocks.append((r,c))
        return blocks

    def manhattan_dist(p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    blocks = sorted(find_2x2_blocks(demo_in))
    print(f"\n=== {demo_name} ({len(blocks)} blocks) ===")

    min_distances = {}
    for i, b1 in enumerate(blocks):
        for j, b2 in enumerate(blocks):
            if i < j:
                d = manhattan_dist(b1, b2)
                if (b1) not in min_distances or d < min_distances[b1]:
                    min_distances[b1] = d

    print("Minimum distances to other blocks:")
    for b, d in sorted(min_distances.items(), key=lambda x: x[1]):
        status = "conv" if ((b[0],b[1]) in [(0,0),(0,11),(1,4),(2,7),(5,15)] if demo_name=='Demo pair 1 input' 
                           else (b in [(0,12),(4,3),(4,7)]) if demo_name=='Demo pair 2 input' else False) else "stay"
        print(f"  {b}: dist={d} -> {status}")

    # Median distance
    if min_distances:
        dists = list(min_distances.values())
        print(f"Median distance: {sorted(dists)[len(dists)//2]}")

import os, re

def load():
