    return G

G = load()

for demo_name in ['Demo pair 1 input', 'Demo pair 2 input']:
    demo_in = G[demo_name]
    h, w = len(demo_in), len(demo_in[0])

    def find_2x2_blocks(grid):
        blocks = []
        for r in range(len(grid)-1):
            for c in range(len(grid[0])-1):
                if grid[r][c] == 2 and grid[r+1][c] == 2 and grid[r][c+1] == 2 and grid[r+1][c+1] == 2:
                    blocks.append((r,c))
        return blocks

    def max_empty_extension(grid, r, c):
        """Find max length of consecutive 0s from any corner of the 2x2 block"""
        max_len = 0

        # From top-left corner (r,c), go up and left
        if r > 0 and c > 0:
            count = 0
            i, j = r-1, c-1
            while 0 <= i < h and 0 <= j < w and grid[i][j] == 0:
                count += 1
                i -= 1
                j -= 1
            max_len = max(max_len, count)

        # From top-right corner (r,c+1), go up and right
        if r > 0 and c+1 < w:
            count = 0
            i, j = r-1, c+1
            while 0 <= i < h and 0 <= j < w and grid[i][j] == 0:
                count += 1
                i -= 1
                j += 1
            max_len = max(max_len, count)

        # From bottom-left corner (r+1,c), go down and left
        if r+1 < h and c > 0:
            count = 0
            i, j = r+2, c-1
            while 0 <= i < h and 0 <= j < w and grid[i][j] == 0:
                count += 1
                i += 1
                j -= 1
            max_len = max(max_len, count)

        # From bottom-right corner (r+1,c+1), go down and right
        if r+1 < h and c+1 < w:
            count = 0
            i, j = r+2, c+1
            while 0 <= i < h and 0 <= j < w and grid[i][j] == 0:
                count += 1
                i += 1
                j += 1
            max_len = max(max_len, count)

        return max_len

    blocks = sorted(find_2x2_blocks(demo_in))
    print(f"\n=== {demo_name} ===")

    conv_info = []
    stay_info = []

    for b in blocks:
        ext = max_empty_extension(demo_in, b[0], b[1])
        if demo_name == 'Demo pair 1 input':
            status = "conv" if b in [(0,0),(0,11),(1,4),(2,7),(5,15)] else "stay"
        elif demo_name == 'Demo pair 2 input':
            status = "conv" if b in [(0,12),(4,3),(4,7)] else "stay"

        if status == "conv":
            conv_info.append((b, ext))
        else:
            stay_info.append((b, ext))

    print("Converting blocks (ext=):")
    for b, ext in sorted(conv_info):
        print(f"  {b}: {ext}")

    print("\nStaying blocks (ext=):")
    for b, ext in sorted(stay_info):
        print(f"  {b}: {ext}")

