# Two blocks are adjacent (connected) if they share a side
# Block A=(r1,c1), B=(r2,c2) share a side if:
#   Same row, columns differ by 1 OR
#   Same col, rows differ by 1

adjacent_pairs = []
for i, b1 in enumerate(blocks_list):
    for j, b2 in enumerate(blocks_list):
        if j > i:
            r1, c1 = b1
            r2, c2 = b2
            # Check horizontal adjacency (same row, adjacent cols)
            if r1 == r2 and abs(c1 - c2) == 1:
                adjacent_pairs.append((b1, b2, 'horizontal'))
            # Check vertical adjacency (same col, adjacent rows)
            elif c1 == c2 and abs(r1 - r2) == 1:
                adjacent_pairs.append((b1, b2, 'vertical'))

