    print(f"  {p[0]} --{p[2]}--> {p[1]}")

# Build connected components using union-find
parent = {b: b for b in blocks_list}
def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

for b1, b2, _ in adjacent_pairs:
    union(b1, b2)

components = {}
for b in blocks_list:
    comp = find(b)
    if comp not in components:
        components[comp] = []
    components[comp].append(b)

