    all_blks = find_2x2_blocks(demo_in)
    min_col = min(b[1] for b in all_blks)
    print(f"Min column among all blocks: {min_col}")
    same_col_blks = [b for b in all_blks if b[1] == min_col]
    print(f"Blocks at column {min_col}: {same_col_blks}")
    print(f"First block is lowest in its column? {fr == min(same_col_blks, key=lambda b: b[0])[0]}")

import os, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()

def find_2x2_blocks(grid):
    blocks = []
    for r in range(len(grid)-1):
        for c in range(len(grid[0])-1):
            if grid[r][c] == 2 and grid[r+1][c] == 2 and grid[r][c+1] == 2 and grid[r+1][c+1] == 2:
                blocks.append((r,c))
    return blocks

# Check: Is first block at absolute (0,0)?
for demo_name in ['Demo pair 1 input', 'Demo pair 2 input', 'Test input']:
    demo_in = G[demo_name]

    def get_expected(demo_name):
        if demo_name == 'Demo pair 1 input':
            return set([(0,0),(0,11),(1,4),(2,7),(5,15)])
        elif demo_name == 'Demo pair 2 input':
            return set([(0,12),(4,3),(4,7)])
        return None

    expected_conv = get_expected(demo_name)
    all_blocks = find_2x2_blocks(demo_in)

    sorted_blks = sorted(all_blocks, key=lambda b: (b[1], b[0]))
    first_block = sorted_blks[0]

    print(f"\n=== {demo_name} ===")
    print(f"First block (col,row sort): {first_block}")
    print(f"At (0,0) absolute? {first_block == (0,0)}")

    # Find actual min row across grid (where any block can be)
    min_grid_rows = [b[0] for b in all_blocks]
    print(f"Rows with blocks: {sorted(set(min_grid_rows))}")

    # Can we select correctly based on whether first is (0,0)?
    n = len(sorted_blks)
    num_select = (n + 1) // 2

    if first_block == (0, 0):
        selected = set(sorted_blks[i] for i in range(0, n, 2))  # evens
    else:
        selected = set(sorted_blks[i] for i in range(1, n, 2))  # odds

    correct = len(selected & expected_conv)
    wrong = len(selected - expected_conv)
    matched = "✓" if correct == len(expected_conv) and wrong == 0 else ""

    print(f"Selected: {sorted(selected)}")
    print(f"Correct: {correct}/{len(expected_conv)}, Wrong: {wrong}{matched}")
